// Application layer: defines the port, no EF reference
public interface IInvoiceRepository {
    Task<Invoice?> GetAsync(Guid id, CancellationToken ct);
    Task AddAsync(Invoice invoice, CancellationToken ct);
}
public class ApproveInvoice(IInvoiceRepository repo, IClock clock) {
    public async Task Handle(Guid id, CancellationToken ct) {
        var inv = await repo.GetAsync(id, ct) ?? throw new NotFoundException(id);
        inv.Approve(clock.UtcNow);          // rule lives in the domain
    }
}
