public interface ITaxRule { bool Applies(Employee e); decimal Compute(Employee e); }

public sealed class PayrollCalculator(IEnumerable<ITaxRule> rules) {
    public decimal NetPay(Employee e) =>
        e.Gross - rules.Where(r => r.Applies(e)).Sum(r => r.Compute(e));
}

