// Decorator: caching added by composition, not inheritance
public sealed class CachedRates(IRates inner, IMemoryCache cache) : IRates {
    public Task<decimal> Get(string ccy) =>
        cache.GetOrCreateAsync(ccy, _ => inner.Get(ccy))!;
}

