public class AgentHub(IAgentRunner agent) : Hub {
    public override async Task OnConnectedAsync() {
        var matter = Context.GetHttpContext()!.Request.Query["matter"];
        await Groups.AddToGroupAsync(Context.ConnectionId, $"matter-{matter}");
    }
    // server-to-client stream: one item per token or agent step
    public async IAsyncEnumerable<string> Ask(string question,
        [EnumeratorCancellation] CancellationToken ct) {
        await foreach (var token in agent.StreamAsync(question, ct))
            yield return token;
    }
}

