[DisallowConcurrentExecution]
public class MonthlyPayrollExport(IPayrollQueries q, IFileStore files) : IJob {
    public async Task Execute(IJobExecutionContext ctx) {
        var rows = await q.MonthRowsAsync(ctx.CancellationToken);
        using var wb = new XLWorkbook();
        wb.AddWorksheet("Payroll").Cell(1, 1).InsertTable(rows);
        using var ms = new MemoryStream();
        wb.SaveAs(ms);
        await files.SaveAsync("payroll.xlsx", ms.ToArray());
    }
}

builder.Services.AddQuartz(q => {
    q.UsePersistentStore(s => { s.UseSqlServer(cs); s.UseClustering(); });
    var key = new JobKey("payroll-export");
    q.AddJob<MonthlyPayrollExport>(key, j => j.RequestRecovery());
    q.AddTrigger(t => t.ForJob(key)
        .WithCronSchedule("0 0 2 1 * ?", c => c.WithMisfireHandlingInstructionFireAndProceed()));
});
builder.Services.AddQuartzHostedService(o => o.WaitForJobsToComplete = true);
